--

DROP TABLE IF EXISTS `flow_forecast`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `flow_forecast` (
  `sta_code` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `datetime` datetime NOT NULL COMMENT 'วัน-เวลา (รายชั่วโมง)',
  `wl` float DEFAULT NULL COMMENT 'ระดับน้ำ, ม.รทก.',
  `discharge` float DEFAULT NULL COMMENT 'อัตราการไหล, ลบ.ม./วินาที',
  UNIQUE KEY `unique_index` (`sta_code`,`datetime`),
