CREATE TABLE `gate_data` (
  `sta_code` varchar(50) DEFAULT NULL COMMENT 'รหัสสถานี',
  `datetime` datetime DEFAULT NULL COMMENT 'วัน-เวลา (รายชั่วโมง)',
  `wl_upper` float DEFAULT NULL COMMENT 'ระดับน้ำเหนือ, ม.รทก.',
  `wl_lower` float DEFAULT NULL COMMENT 'ระดับน้ำท้าย, ม.รทก.',
