  UNIQUE KEY `unique_index` (`sta_code`,`datetime`),
  CONSTRAINT `gate_data_ibfk_1` FOREIGN KEY (`sta_code`) REFERENCES `gate_info` (`sta_code`) ON DELETE CASCADE ON UPDATE CASCADE
