DROP TABLE IF EXISTS `gate_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `gate_info` (
  `no` int(11) NOT NULL COMMENT 'ลำดับ',
  `sta_code` varchar(20) NOT NULL,
  `sta_name` varchar(255) NOT NULL COMMENT 'ชื่อสถานี',
  `gate_no` int(11) NOT NULL COMMENT 'จำนวนบานระบาย',
  `gate_height` decimal(5,2) NOT NULL COMMENT 'ความสูงบาน,เมตร',
  `tambon` varchar(255) DEFAULT NULL COMMENT 'ที่ตั้ง',
  `district` varchar(255) DEFAULT NULL COMMENT 'อำเภอ',
  `province` varchar(255) DEFAULT NULL COMMENT 'จังหวัด',
  `capacity` double DEFAULT NULL COMMENT 'ความจุ, ลบ.ม./วินาที',
  `lat` float DEFAULT NULL COMMENT 'latitude',
  `long` float DEFAULT NULL COMMENT 'longitude',
  `type` varchar(50) DEFAULT NULL,
  `photo` varchar(255) DEFAULT NULL COMMENT 'รูปภาพสถานี',
  PRIMARY KEY (`sta_code`,`sta_name`),
  KEY `no` (`no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='ข้อมูลประตูระบายน้ำ';
/*!40101 SET character_set_client = @saved_cs_client */;

