--
-- Table structure for table `reservoir_info`
--

DROP TABLE IF EXISTS `reservoir_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `reservoir_info` (
  `no` int(11) NOT NULL AUTO_INCREMENT COMMENT 'ลำดับ',
  `res_code` varchar(100) NOT NULL COMMENT 'รหัสอ่างเก็บน้ำ',
  `rid_code` varchar(100) NOT NULL COMMENT 'รหัสจากกรมชลประทาน',
  `res_name` varchar(255) DEFAULT NULL COMMENT 'ชื่ออ่างเก็บน้ำ',
  `tambon` varchar(255) DEFAULT NULL COMMENT 'ตำบล',
  `district` varchar(255) DEFAULT NULL COMMENT 'อำเภอ',
  `province` varchar(255) DEFAULT NULL COMMENT 'จังหวัด',
  `type` varchar(20) DEFAULT NULL COMMENT 'ชนิด (หลัก, รอง)',
  `size` char(20) DEFAULT NULL COMMENT 'ขนาดเขื่อน (ใหญ่ กลาง เล็ก)',
  `owner` varchar(50) DEFAULT NULL COMMENT 'หน่วยงานเจ้าของเขื่อน',
  `long` double DEFAULT NULL COMMENT 'longitude',
  `lat` double DEFAULT NULL COMMENT 'latititude',
  `da_km2` double DEFAULT NULL COMMENT 'พื้นที่รับน้ำ, ตร.กม.',
  `maxvol` double DEFAULT NULL COMMENT 'ปริมาตรน้ำสูงสุด, ล้าน ลบ.ม.',
  `nhvol` double DEFAULT NULL COMMENT 'ปริมตรน้ำเก็บกัก, ล้าน ลบ.ม.',
  `minvol` double DEFAULT NULL COMMENT 'ปริมาตรน้ำต่ำสุด, ล้าน ลบ.ม.',
  `maxwl` double DEFAULT NULL COMMENT 'ระดับน้ำสูงสุด, ม.รทก.',
  `nhwl` double DEFAULT NULL COMMENT 'ระดับน้ำเก็บกัก, ม.รทก.',
  `minwl` double DEFAULT NULL COMMENT 'ระดับน้ำต่ำสุด, ม.รทก.',
  `inflow_avg` double DEFAULT NULL COMMENT 'ปริมาณน้ำไหลเข้าอ่างเฉลี่ยรายปี, ล้าน ลบ.ม.',
  `photo` varchar(255) DEFAULT NULL COMMENT 'รูปภาพสถานี',
  PRIMARY KEY (`res_code`,`rid_code`),
  KEY `no` (`no`)
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='ข้อมูลทั่วไปอ่างเก็บน้ำ';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `reservoir_info`
--

LOCK TABLES `reservoir_info` WRITE;
/*!40000 ALTER TABLE `reservoir_info` DISABLE KEYS */;
